INSERT INTO #AsProfiles (Name, Title, EntityLower, EntityPascal, CustomQuery, ColumnsJson, ActionOptions, CustomButtons) VALUES (N'AfterSales_TechnicalQuery_ApproveQueue', N'بررسی و تایید پرسش فنی', N'entities.app.sale.technicalquery', N'Entities.App.Sale.TechnicalQuery', N'SELECT
    [t1].[Id] AS [t1_Id],
    [t1].[HtsId] AS [t1_HtsId],
    [t1].[CartableStatusId] AS [t1_CartableStatusId],
    [t3].[FullName] AS [t3_FullName],
    [t4].[Code] AS [t4_Code],
    [t4].[Name] AS [t4_Name],
    [t1].[Serial] AS [t1_Serial],
    [t5].[Name] AS [t5_Name],
    [t1].[TechnicalProblemDescription] AS [t1_TechnicalProblemDescription],
    [t1].[InstallationShamsiDate] AS [t1_InstallationShamsiDate],
    [t1].[FirstEmergingProblemShamsiDate] AS [t1_FirstEmergingProblemShamsiDate],
    [t1].[LastEmergingProblemShamsiDate] AS [t1_LastEmergingProblemShamsiDate],
    [t1].[NumberOfEmergedProblem] AS [t1_NumberOfEmergedProblem],
    [t1].[InApproveQueue] AS [t1_InApproveQueue],
    [t1].[CreatedByName] AS [t1_CreatedByName],
    [t1].[CreatedOnShamsiDateTime] AS [t1_CreatedOnShamsiDateTime]
FROM [Sale].[TechnicalQuery] AS [t1]
LEFT JOIN [SLS].[Customer] AS [t2] ON [t1].[CustomerId] = [t2].[Id]
LEFT JOIN [Gnr].[Party] AS [t3] ON [t2].[PartyId] = [t3].[Id]
LEFT JOIN [Inv].[Part] AS [t4] ON [t1].[PartId] = [t4].[Id]
LEFT JOIN [Gnr].[Region] AS [t5] ON [t1].[ProvinceId] = [t5].[Id]
WHERE [t1].[CartableStatusId] IS NOT NULL', N'[{"TableName":"Sale.TechnicalQuery","ColumnName":"Id","DisplayName":"شناسه","Alliance":"t1_Id","Address":"[t1].[Id]","SystemTypeName":"Long","SelectIndex":0,"Visible":false,"PrimaryKey":true,"SystemType":6,"SortDirection":1,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":80,"Filterable":true,"Sortable":true,"ClassName":""},
